(* [comment removed for export] *)
Ltac2 fit_clear_arith () : unit :=
  let ids := List.map_filter (fun h => let (id, body, ty) := h in
      match body with
      | Some _ => None
      | None => if Bool.and (LiaTuning.zt_is_local id)
                     (Bool.and (LiaTuning.zt_is_prop ty) (Bool.or (LiaTuning.zt_plain_arith ty) (LiaTuning.zt_twoway ty)))
                then Some id else None
      end) (Control.hyps ()) in
  match ids with [] => () | _ :: _ => Std.clear ids end.
Local Ltac qtauto :=
  first [ solve [ lazymatch goal with H : _ |- _ => clear - H end; tauto ]     (* [comment removed for export] *)
        | solve [ ltac2:(Control.enter fit_clear_arith); tauto ]             (* [comment removed for export] *)
        | tauto ].
(* [comment removed for export] *)
Local Ltac notrap ::=
  let K := fresh "KT" in
  step; if_cases K; zify_cond K;
  [ exfalso;
    first [ rewrite land7_mod8 in K; first [ match goal with H : _ |- _ => exact (K H) end | lia ]
          | lia
          | rewrite land3_mod4 in K; first [ match goal with H : _ |- _ => exact (K H) end | lia ]
          | rewrite lxor_m1_64 in K by lia; lia
          | rewrite land6_of_mod8 in K by lia; lia
          | rewrite land4_of_mod8 in K by lia; lia
          | let t := type of K in fail 100 "notrap: cannot refute the trap condition" t ]
  | clear K ].

